1	package world
2	
3	import (
4		"fmt"
5		"math"
6		"unicode/utf8"
7	)
8	
9	// NameMapping 描述旧规则中一个名称到新规则名称的显式转换关系。
10	//
11	// From 必须是来源记录旧规则中存在的地点或物品种类，To 必须是目标规则中
12	// 存在的对应名称；空名称、来源不存在于旧规则或目标不存在于新规则都在
13	// 预览时返回规则错误。
14	type NameMapping struct {
15		// From 是旧规则中的地点或物品种类名称。
16		From string
17		// To 是新规则中的对应名称。
18		To string
19	}
20	
21	// MigrationPreview 是把槽当前最新记录按对应关系显式迁移到目标规则的
22	// 预览结果。
23	//
24	// 预览只读：返回所依据的来源记录标识、旧新版本、按对应关系转换后的完整
25	// 世界状态（深拷贝）以及是否可提交。它不改变槽指向、历史或任何记录文件；
26	// 修改返回的状态也不影响存档。
27	type MigrationPreview struct {
28		// RecordID 是所依据的来源记录标识（槽当前最新记录）。
29		RecordID RecordID
30		// OldVersion 是来源记录的规则版本。
31		OldVersion string
32		// TargetVersion 是目标规则版本。
33		TargetVersion string
34		// State 是转换后的完整世界状态（深拷贝），规则已替换为目标规则。
35		// 正式迁移以排他锁下重新读取和计算的结果为准，不使用调用方可能改过
36		// 的本状态。
37		State State
38		// Committable 表示转换后的状态能否在目标规则下提交（无阻碍）。
39		Committable bool
40		// Blockers 是全部阻碍，排序与升级检查一致；重复预览输出顺序一致。
41		Blockers []Blocker
42	}
43	
44	// MigrationResult 是正式迁移的返回结果。
45	type MigrationResult struct {
46		// Preview 是对来源记录与目标规则的预览结果（排他锁下重新读取并计算）。
47		Preview MigrationPreview
48		// Record 是成功时新记录的元信息；被阻碍时为零值。
49		Record RecordInfo
50	}
51	
52	// validateMappings 校验转换对应关系：来源必须存在于旧规则，目标必须存在
53	// 于新规则，名称非空，同一来源不重复指定。即使没有角色使用这些名称也要
54	// 检查。
55	func validateMappings(old, target Rules, locations, items []NameMapping) error {
56		oldLocs := make(map[string]struct{}, len(old.Locations))
57		for _, l := range old.Locations {
58			oldLocs[l] = struct{}{}
59		}
60		newLocs := make(map[string]struct{}, len(target.Locations))
61		for _, l := range target.Locations {
62			newLocs[l] = struct{}{}
63		}
64		if err := validateMappingSet("地点", locations, oldLocs, newLocs); err != nil {
65			return err
66		}
67	
68		oldKinds := make(map[string]struct{}, len(old.ItemKinds))
69		for _, k := range old.ItemKinds {
70			oldKinds[k] = struct{}{}
71		}
72		newKinds := make(map[string]struct{}, len(target.ItemKinds))
73		for _, k := range target.ItemKinds {
74			newKinds[k] = struct{}{}
75		}
76		return validateMappingSet("物品种类", items, oldKinds, newKinds)
77	}
78	
79	func validateMappingSet(kind string, mappings []NameMapping, oldNames, newNames map[string]struct{}) error {
80		seen := make(map[string]struct{}, len(mappings))
81		for i, m := range mappings {
82			if !utf8.ValidString(m.From) {
83				return ruleErrorf("%s转换关系 %d 的来源名称不是合法 UTF-8: %q", kind, i, m.From)
84			}
85			if !utf8.ValidString(m.To) {
86				return ruleErrorf("%s转换关系 %d 的目标名称不是合法 UTF-8: %q", kind, i, m.To)
87			}
88			if m.From == "" {
89				return ruleErrorf("%s转换关系 %d 的来源名称为空", kind, i)
90			}
91			if m.To == "" {
92				return ruleErrorf("%s转换关系 %d 的目标名称为空", kind, i)
93			}
94			if _, ok := oldNames[m.From]; !ok {
95				return ruleErrorf("%s转换关系的来源 %q 不存在于旧规则", kind, m.From)
96			}
97			if _, ok := newNames[m.To]; !ok {
98				return ruleErrorf("%s转换关系的目标 %q 不存在于新规则", kind, m.To)
99			}
100			if _, dup := seen[m.From]; dup {
101				return ruleErrorf("%s转换关系的来源 %q 重复指定", kind, m.From)
102			}
103			seen[m.From] = struct{}{}
104		}
105		return nil
106	}
107	
108	// applyMigration 按对应关系转换状态：角色按对应关系改变所在地点（无需
109	// 符合旧道路），物品改变种类但不增减数量；多个条目转换成同一种物品时
110	// 合并数量，按原列表中首次出现的位置保留一个条目。转换只作用于原始名称
111	// 一次，不沿对应关系连续替换，因此互换名称也有确定结果。未指定的名称
112	// 保持原样。种子、时间片、角色标识及角色排列保持不变。
113	//
114	// 合并数量或携带总量超出 int 范围时返回规则错误，不回绕也不丢弃物品。
115	func applyMigration(st State, locations, items []NameMapping) (State, error) {
116		locLookup := make(map[string]string, len(locations))
117		for _, m := range locations {
118			locLookup[m.From] = m.To
119		}
120		itemLookup := make(map[string]string, len(items))
121		for _, m := range items {
122			itemLookup[m.From] = m.To
123		}
124	
125		out := cloneState(st)
126	
127		for i := range out.Characters {
128			if to, ok := locLookup[out.Characters[i].Location]; ok {
129				out.Characters[i].Location = to
130			}
131		}
132	
133		for i := range out.Characters {
134			ch := &out.Characters[i]
135			merged := make([]CharacterItem, 0, len(ch.Items))
136			indexByName := make(map[string]int, len(ch.Items))
137			for _, it := range ch.Items {
138				name := it.Item
139				if to, ok := itemLookup[name]; ok {
140					name = to
141				}
142				if idx, ok := indexByName[name]; ok {
143					sum, ok := addInt(merged[idx].Count, it.Count)
144					if !ok {
145						return State{}, ruleErrorf("角色 %q 的物品 %q 合并数量超出整数范围", ch.ID, name)
146					}
147					merged[idx].Count = sum
148				} else {
149					indexByName[name] = len(merged)
150					merged = append(merged, CharacterItem{Item: name, Count: it.Count})
151				}
152			}
153			ch.Items = merged
154	
155			// 携带总量溢出检查：各物品数量都合法，但不同物品相加可能超出
156			// int 范围，同样不能回绕或丢弃。这是显式迁移特有的整数范围门槛，
157			// 与携带上限判断不同：无论目标规则是否给该角色设置上限，真实总量
158			// 超出 int 范围都拒绝，不能因为共用总量判断而把“无上限”当成允许
159			// 溢出迁移。精确求和与其余入口共用 carryTotal，此处只保留自己的
160			// 溢出判定。
161			if carryTotal(ch.Items).Cmp(maxIntBig) > 0 {
162				return State{}, ruleErrorf("角色 %q 携带总量超出整数范围", ch.ID)
163			}
164		}
165		return out, nil
166	}
167	
168	// addInt 做一次带溢出检查的 int 加法，返回结果与是否溢出。
169	func addInt(a, b int) (int, bool) {
170		if b > 0 && a > math.MaxInt-b {
171			return 0, false
172		}
173		if b < 0 && a < math.MinInt-b {
174			return 0, false
175		}
176		return a + b, true
177	}
178	
179	// migrationComputeLocked 在调用方已持锁（共享或排他均可）的前提下读取并
180	// 校验槽当前最新记录，校验转换对应关系，计算转换后的状态与阻碍。来源
181	// 读取、完整性检查、可接受版本与版本相异判断共用
182	// sourceForTransformLocked，本函数只负责迁移自己的对应关系校验、转换与
183	// 阻碍计算。不写入。
184	func (a *Archive) migrationComputeLocked(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping) (MigrationPreview, *envelope, error) {
185		latest, env, err := a.sourceForTransformLocked(slot, acceptedVersions, target.Version)
186		if err != nil {
187			return MigrationPreview{}, nil, err
188		}
189		if err := validateMappings(env.State.Rules, target, locations, items); err != nil {
190			return MigrationPreview{}, nil, err
191		}
192		transformed, err := applyMigration(env.State, locations, items)
193		if err != nil {
194			return MigrationPreview{}, nil, err
195		}
196		// 转换后的状态保存目标规则。
197		transformed.Rules = cloneRules(target)
198		blockers := checkCompatibility(transformed, target)
199		preview := MigrationPreview{
200			RecordID:      latest,
201			OldVersion:    env.State.Rules.Version,
202			TargetVersion: target.Version,
203			State:         transformed,
204			Committable:   len(blockers) == 0,
205			Blockers:      blockers,
206		}
207		return preview, env, nil
208	}
209	
210	// PreviewMigration 预览把槽当前最新记录按对应关系显式迁移到目标规则。
211	//
212	// 传入槽名、可接受的旧版本集合、目标规则，以及旧地点到新地点、旧物品到
213	// 新物品的对应关系，返回所依据的来源记录标识、旧新版本、转换后的完整
214	// 世界状态（深拷贝）及是否可提交。转换只作用于原始名称一次，不沿对应
215	// 关系连续替换；未指定的名称保持原样。转换后仍有缺失地点、不被允许的
216	// 物品或超过目标携带上限时，一次列出全部阻碍，重复预览输出顺序一致。
217	//
218	// 预览只读：不改变世界、历史或槽当前记录，修改返回的状态也不影响存档。
219	// 目标规则须满足规则自身的合法性要求且版本与来源不同；对应关系的来源
220	// 必须存在于旧规则、目标必须存在于新规则（即使没有角色使用也要检查），
221	// 空目标或未知名称返回规则错误；合并数量或携带总量超出 int 范围返回规则
222	// 错误。来源缺失、损坏或版本不被接受时沿用已有对应错误，不自动挑选历史
223	// 记录。槽指针无法解析，或顶层 latest/history 字段重复（含义有歧义）时
224	// 返回带槽名的 *CorruptError，先于来源与版本判断，不返回任何预览内容。
225	func (a *Archive) PreviewMigration(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping) (MigrationPreview, error) {
226		if !validSlotName(slot) {
227			return MigrationPreview{}, &NotFoundError{Slot: slot}
228		}
229		if err := validateRules(target); err != nil {
230			return MigrationPreview{}, err
231		}
232		lock, err := acquireSharedLock(a.dir)
233		if err != nil {
234			return MigrationPreview{}, err
235		}
236		defer lock.release()
237		preview, _, err := a.migrationComputeLocked(slot, acceptedVersions, target, locations, items)
238		if err != nil {
239			return MigrationPreview{}, err
240		}
241		return preview, nil
242	}
243	
244	// Migrate 在预览后正式迁移：用目标规则与转换后的状态生成一条以来源为父
245	// 的新记录并加入本槽保存次序。
246	//
247	// 传入与预览相同的条件，并带预览返回的来源记录标识 source。提交时在
248	// 排他锁下重新读取并完整校验来源，重新校验目标规则与对应关系、重新计算
249	// 转换后的状态与阻碍，绝不使用调用方可能改过的预览状态：
250	//
251	//   - source 为空，或槽已不再指向该来源（被并发覆盖、升级、确认恢复或
252	//     另一次迁移抢先提交），返回 *ConflictError。
253	//   - 槽指针无法解析，或顶层 latest/history 字段重复（含义有歧义）时，
254	//     返回带槽名的 *CorruptError：无法确定当前来源与待承接历史，不产生
255	//     新记录，不修补指针。
256	//   - 来源缺失、损坏或版本不被接受分别返回已有的不存在、损坏或版本拒绝
257	//     错误，不改选其他记录。
258	//   - 仍有阻碍时返回阻碍信息并拒绝保存，不改变当前记录或历史。
259	//
260	// 成功后产生一条以来源为父的新记录，保存目标规则与转换后的状态，加入
261	// 本槽保存次序；种子、时间片、角色标识及角色排列保持原样。与覆盖、升级、
262	// 确认恢复或另一次迁移竞争时，同一来源最多一个成功。任何拒绝都不改变
263	// 当前记录或历史；中断后重开只能看到迁移前或迁移后的完整记录与历史。
264	// 旧记录及已有分支保留原状态，恢复读取仍能找到旧版本；迁移后的记录可
265	// 继续按新规则移动、改变物品并保存，普通读取不自动转换。
266	func (a *Archive) Migrate(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping, source RecordID) (MigrationResult, error) {
267		if !validSlotName(slot) {
268			return MigrationResult{}, &NotFoundError{Slot: slot}
269		}
270		if source == "" {
271			return MigrationResult{}, &ConflictError{Slot: slot, Reason: "迁移必须提供所依据的来源记录标识"}
272		}
273		if err := validateRules(target); err != nil {
274			return MigrationResult{}, err
275		}
276		lock, err := acquireLock(a.dir)
277		if err != nil {
278			return MigrationResult{}, err
279		}
280		defer lock.release()
281	
282		oldPointer, err := a.readSlotPointerLocked(slot)
283		if err != nil {
284			return MigrationResult{}, err
285		}
286		// 乐观并发控制：槽必须仍指向预览时的来源记录。
287		if oldPointer.Latest != source {
288			return MigrationResult{}, &ConflictError{
289				Slot:   slot,
290				Reason: "所依据的来源记录已不是该槽最新记录",
291			}
292		}
293	
294		// 排他锁下重新读取、校验并计算，不采信调用方带回的任何状态。
295		preview, _, err := a.migrationComputeLocked(slot, acceptedVersions, target, locations, items)
296		if err != nil {
297			return MigrationResult{}, err
298		}
299		if !preview.Committable {
300			return MigrationResult{Preview: preview}, &RuleError{
301				Reason: fmt.Sprintf("迁移被阻碍: 转换后的状态无法在目标规则下提交（%d 处阻碍）", len(preview.Blockers)),
302			}
303		}
304	
305		// 保存目标规则与排他锁下重新计算出的转换结果；以来源为父，沿用
306		// 共同的新记录组装、落盘与槽指针提交路径。记录完整落盘后才原子
307		// 更新指针：新记录前置进保存次序，旧历史原样保留。崩溃在这一步
308		// 之前时槽保持迁移前的指向与历史，新记录因不在历史索引中而不会
309		// 进入恢复候选。
310		info, err := a.appendSlotRecordLocked(slotSave{
311			slot:          slot,
312			oldPointer:    oldPointer,
313			parent:        source,
314			historyAnchor: source,
315			state:         preview.State,
316		})
317		if err != nil {
318			return MigrationResult{}, err
319		}
320		return MigrationResult{Preview: preview, Record: info}, nil
321	}
322

