972		a, dir := newTestArchive(t)
973		info := saveBase(t, a, "s")
974	
975		const n = 8
976		var wg sync.WaitGroup
977		var mu sync.Mutex
978		wins, conflicts := 0, 0
979		errs := make([]error, 0)
980		for i := 0; i < n; i++ {
981			wg.Add(1)
982			go func() {
983				defer wg.Done()
984				ga, err := Open(dir)
985				if err != nil {
986					mu.Lock()
