992				mu.Lock()
993				defer mu.Unlock()
994				switch {
995				case uerr == nil:
996					wins++
997				case isConflict(uerr):
998					conflicts++
999				default:
1000					errs = append(errs, uerr)
1001				}
1002			}()
1003		}
1004		wg.Wait()
1005		if len(errs) != 0 {
