20	// Blocker 描述一条“目标规则无法原样承接当前角色状态”的具体阻碍。
21	type Blocker struct {
22		// Character 是受阻碍的角色标识。
23		Character string
24		// Kind 是阻碍类型。
25		Kind BlockerKind
26		// Location 是缺失的地点（Kind 为 BlockerLocation 时有值）。
27		Location string
28		// Item 是被移除的物品种类（Kind 为 BlockerItem 时有值）。
29		Item string
30		// Total 是角色当前携带总量（Kind 为 BlockerLimit 且 TotalOverflow
31		// 为 false 时有值，此时它就是真实总量）。
32		Total int
33		// TotalOverflow 表示真实携带总量超出 int 能表示的范围（来源规则未设
34		// 上限时可能出现）：此时 Total 不代表实际总量，调用方应改用
