64	}
65	
66	// checkCompatibility 计算用 target 规则原样承接 st 中全部角色状态的阻碍。
67	//
68	// 兼容只判断能否原样承接当前角色状态：每个角色所在地点仍存在，已列出的
69	// 物品种类仍被允许（数量为零也算），各角色携带总量不超过目标上限（按真实
70	// 总量精确求和，不因回绕放过超限；真实总量超出 int 范围时阻碍置
71	// TotalOverflow 并以 TotalText 给出完整十进制总量）；目标中没有该角色上限
72	// 时表示不设上限。允许删去无人所在的地点、不再出现的物品种类或旧连通关系，
73	// 也允许增加内容。升级后移动和物品变化按目标规则处理。
74	func checkCompatibility(st State, target Rules) []Blocker {
75		locSet := make(map[string]struct{}, len(target.Locations))
76		for _, l := range target.Locations {
77			locSet[l] = struct{}{}
78		}
79		kindSet := make(map[string]struct{}, len(target.ItemKinds))
80		for _, k := range target.ItemKinds {
81			kindSet[k] = struct{}{}
82		}
83		var blockers []Blocker
84		for _, ch := range st.Characters {
85			if _, ok := locSet[ch.Location]; !ok {
86				blockers = append(blockers, Blocker{
87					Character: ch.ID,
88					Kind:      BlockerLocation,
89					Location:  ch.Location,
90				})
91			}
92			for _, it := range ch.Items {
93				if _, ok := kindSet[it.Item]; !ok {
94					blockers = append(blockers, Blocker{
95						Character: ch.ID,
96						Kind:      BlockerItem,
97						Item:      it.Item,
98					})
99				}
100			}
101			// 携带上限按真实总量判断，与建立/重建世界、提交物品变化共用同一
102			// 口径（精确求和不因回绕放过超限，目标中没有该角色上限时表示不设
103			// 上限）。真实总量能用 int 表示时沿用 Total 字段；超出 int 范围时
104			// 置 TotalOverflow 并给出完整十进制 TotalText，绝不返回回绕值。
105			if limit, ok := target.CarryLimits[ch.ID]; ok {
106				total := carryTotal(ch.Items)
107				if totalExceedsLimit(total, limit) {
108					b := Blocker{
109						Character: ch.ID,
110						Kind:      BlockerLimit,
111						Limit:     limit,
112					}
113					if total.Cmp(maxIntBig) <= 0 {
114						b.Total = int(total.Int64())
115					} else {
116						b.TotalOverflow = true
117						b.TotalText = total.String()
118					}
119					blockers = append(blockers, b)
120				}
121			}
122		}
123		// 同类问题按角色标识、物品标识排序；location/limit 阻碍没有物品标识，
124		// 以空物品标识参与排序，保证重复检查输出顺序一致。跨类别按
125		// location、item、limit 的自然顺序分组，便于阅读。
126		kindRank := func(k BlockerKind) int {
127			switch k {
128			case BlockerLocation:
129				return 0
130			case BlockerItem:
131				return 1
132			case BlockerLimit:
133				return 2
134			}
135			return 3
136		}
137		sort.SliceStable(blockers, func(i, j int) bool {
138			if blockers[i].Character != blockers[j].Character {
139				return blockers[i].Character < blockers[j].Character
140			}
141			if blockers[i].Kind != blockers[j].Kind {
142				return kindRank(blockers[i].Kind) < kindRank(blockers[j].Kind)
143			}
144			return blockers[i].Item < blockers[j].Item
145		})
146		return blockers
147	}
148	
149	// checkUpgradeLocked 在调用方已持锁（共享或排他均可）的前提下读取并校验
150	// 槽当前最新记录，计算目标规则的兼容性。来源读取、完整性检查、可接受
151	// 版本与版本相异判断共用 sourceForTransformLocked，本函数只负责升级自己
152	// 的兼容性计算。返回检查结果与来源记录信封。
153	func (a *Archive) checkUpgradeLocked(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, *envelope, error) {
154		latest, env, err := a.sourceForTransformLocked(slot, acceptedVersions, target.Version)
155		if err != nil {
156			return UpgradeCheck{}, nil, err
157		}
158		check := UpgradeCheck{
159			RecordID:      latest,
160			OldVersion:    env.State.Rules.Version,
161			TargetVersion: target.Version,
162		}
163		blockers := checkCompatibility(env.State, target)
164		check.Compatible = len(blockers) == 0
165		check.Blockers = blockers
166		return check, env, nil
167	}
168	
169	// CheckUpgrade 检查槽当前最新记录能否在目标规则下继续使用。
170	//
171	// 检查只读取来源记录并计算兼容性，不改变世界、历史或槽当前记录，也不会
172	// 替换记录中的规则。target 必须先满足规则自身的合法性要求，且版本与来源
173	// 记录不同（版本只按相等判断，不按数字大小限制升级）。
174	//
175	// 目标规则非法返回 *RuleError；版本相同返回 *RuleError；来源损坏返回
176	// *CorruptError；来源版本不在 acceptedVersions 内返回 *VersionRejectedError；
177	// 槽不存在沿用现有不存在错误。槽指针无法解析，或顶层 latest/history 字段
178	// 重复（含义有歧义）时也返回带槽名的 *CorruptError，且先于来源与版本判断。
179	func (a *Archive) CheckUpgrade(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, error) {
180		if !validSlotName(slot) {
181			return UpgradeCheck{}, &NotFoundError{Slot: slot}
182		}
183		if err := validateRules(target); err != nil {
184			return UpgradeCheck{}, err
185		}
186		lock, err := acquireSharedLock(a.dir)
187		if err != nil {
188			return UpgradeCheck{}, err
189		}
190		defer lock.release()
191		check, _, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
192		if err != nil {
193			return UpgradeCheck{}, err
194		}
195		return check, nil
196	}
197	
198	// Upgrade 在检查通过后用目标规则生成一条新记录。
199	//
200	// 传入与 CheckUpgrade 相同的条件，并带调用方预期的最新记录标识 expected。
201	// 提交时在排他锁下重新判断当前来源：仍有阻碍则返回相同的阻碍信息并拒绝
202	// 写入；expected 为空或已不是该槽最新记录时返回现有冲突错误；槽指针无法
203	// 解析或顶层 latest/history 字段重复（含义有歧义）时返回带槽名的
204	// *CorruptError，不产生新记录也不修补指针。
205	//
206	// 被拒绝的升级不增加历史记录，也不改变槽当前记录。成功后槽增加一条完整
207	// 的新记录，以被升级记录为父，保存目标规则；种子、时间片、角色位置及
208	// 物品数量和排列保持原样。并发升级或升级与普通覆盖竞争时，只有 expected
209	// 与最新记录一致的一个成功，其余收到冲突。
210	func (a *Archive) Upgrade(slot string, acceptedVersions []string, target Rules, expected RecordID) (UpgradeResult, error) {
211		if !validSlotName(slot) {
212			return UpgradeResult{}, &NotFoundError{Slot: slot}
213		}
214		if err := validateRules(target); err != nil {
215			return UpgradeResult{}, err
216		}
217		if expected == "" {
218			return UpgradeResult{}, &ConflictError{Slot: slot, Reason: "升级必须提供所依据的记录标识"}
219		}
220		lock, err := acquireLock(a.dir)
221		if err != nil {
222			return UpgradeResult{}, err
223		}
224		defer lock.release()
225	
226		oldPointer, err := a.readSlotPointerLocked(slot)
227		if err != nil {
228			return UpgradeResult{}, err
229		}
230		latest := oldPointer.Latest
231		if latest != expected {
232			return UpgradeResult{}, &ConflictError{
233				Slot:   slot,
234				Reason: "所依据的记录已不是该槽最新记录",
235			}
236		}
237	
238		check, env, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
239		if err != nil {
240			return UpgradeResult{}, err
241		}
242		if !check.Compatible {
243			return UpgradeResult{Check: check}, &RuleError{
244				Reason: fmt.Sprintf("升级被阻碍: 目标规则无法承接当前角色状态（%d 处阻碍）", len(check.Blockers)),
245			}
246		}
247	
248		// 升级保存目标规则，种子、时间片、角色位置及物品数量和排列原样保留；
249		// 以被升级记录为父，沿用共同的新记录组装、落盘与槽指针提交路径。
250		newState := State{
251			Seed:       env.State.Seed,
252			Rules:      cloneRules(target),
253			Time:       env.State.Time,
254			Characters: cloneCharacters(env.State.Characters),
255		}
256		info, err := a.appendSlotRecordLocked(slotSave{
257			slot:          slot,
258			oldPointer:    oldPointer,
259			parent:        expected,
260			historyAnchor: latest,
261			state:         newState,
262		})
263		if err != nil {
264			return UpgradeResult{}, err
265		}
266		return UpgradeResult{Check: check, Record: info}, nil
267	}
