	Compatible bool
	// Blockers 是全部阻碍，按角色标识、物品标识排序；重复检查输出顺序一致。
	Blockers []Blocker
}

// UpgradeResult 是升级的返回结果。
type UpgradeResult struct {
	// Check 是对当前来源记录与目标规则的兼容性检查结果。
	Check UpgradeCheck
